using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.Windows.Forms;
namespace UnturnedModManager {
 public static class DashboardTests {
  static List<string> results;static void Check(bool value,string message){if(!value)throw new Exception("FAIL "+message);results.Add("PASS "+message);Console.WriteLine(results.Last());}
  static Package PackageAt(string folder,string id,string target){string source="payload/"+target;string full=Paths.Safe(folder,source);Directory.CreateDirectory(Path.GetDirectoryName(full));File.WriteAllText(full,"fixture "+id);Data.Write(Path.Combine(folder,Packages.ManifestName),new PackageManifest{schemaVersion=1,id=id,name="Original "+id,kind="module",version="1.0.0",files=new List<PackageFile>{new PackageFile{source=source,target=target,sha256=Data.Hash(full)}}});return Packages.Load(folder,"fixture");}
  static MetadataDocument Names(Package package){return new MetadataDocument{schemaVersion=1,mods=new List<ModMetadata>{new ModMetadata{modId=package.Manifest.id,type="module",displayNames=new Dictionary<string,string>{{"zh-TW","測試工具"},{"zh-CN","测试工具"},{"en-US","Fixture tool"}}}}};}
  public static int Run(string output){results=new List<string>();string root=Path.Combine(Path.GetFullPath(output),"dashboard-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string game=Path.Combine(root,"game"),state=Path.Combine(root,"state"),source=Path.Combine(root,"sources");Directory.CreateDirectory(game);File.WriteAllText(Path.Combine(game,"Unturned.exe"),"fixture only");var good=PackageAt(Path.Combine(source,"good"),"test.localized","Modules/Good/a.dll");var names=Names(good);Data.Write(Path.Combine(good.Folder,ModNames.FileName),names);good=Packages.Load(good.Folder,"fixture");string identity=good.Manifest.id;string target=good.Manifest.files[0].target;foreach(string code in L.Languages){L.Language=code;Check(ModNames.Display(good)==names.mods[0].displayNames[code],"metadata display in "+code);Check(ModNames.Search(good).Contains("測試工具")&&ModNames.Search(good).Contains("Fixture tool"),"all-language search in "+code);}Check(identity==good.Manifest.id&&target==good.Manifest.files[0].target,"localized display leaves identity and targets unchanged");
   names.mods[0].displayNames.Remove("en-US");Data.Write(Path.Combine(good.Folder,ModNames.FileName),names);L.Language="en-US";Check(ModNames.Display(Packages.Load(good.Folder,"fixture"))=="測試工具","missing English falls back to Traditional Chinese");names.mods[0].displayNames.Remove("zh-TW");Data.Write(Path.Combine(good.Folder,ModNames.FileName),names);Check(ModNames.Display(Packages.Load(good.Folder,"fixture"))==good.Manifest.name,"missing fallback uses original author name");Check(ModNames.Display(null,"",identity)==identity,"empty original falls back to stable ID");
   names=Names(good);names.mods[0].modId="wrong.id";Data.Write(Path.Combine(good.Folder,ModNames.FileName),names);var invalid=Packages.Load(good.Folder,"fixture");Check(invalid.Metadata==null&&invalid.MetadataIssue!=null,"mismatched metadata is ignored with a diagnostic");names=Names(good);names.mods.Add(names.mods[0]);Data.Write(Path.Combine(good.Folder,ModNames.FileName),names);Check(Packages.Load(good.Folder,"fixture").Metadata==null,"duplicate metadata IDs rejected");names=Names(good);names.mods[0].displayNames["en-US"]="unsafe\nname";Data.Write(Path.Combine(good.Folder,ModNames.FileName),names);Check(Packages.Load(good.Folder,"fixture").Metadata==null,"control characters in metadata rejected");File.WriteAllText(Path.Combine(good.Folder,ModNames.FileName),"{");Check(Packages.Load(good.Folder,"fixture").Metadata==null,"malformed metadata does not hide a valid package");Data.Write(Path.Combine(good.Folder,ModNames.FileName),Names(good));using(var session=new ScanSession(System.Threading.CancellationToken.None)){ScanCache.Read(good.Folder,"fixture");ScanCache.Read(good.Folder,"fixture");Check(session.CacheHits>=1,"metadata is cached with package parsing");var updated=Names(good);updated.mods[0].displayNames["en-US"]="Updated fixture tool";Data.Write(Path.Combine(good.Folder,ModNames.FileName),updated);Check(ScanCache.Read(good.Folder,"fixture")[0].Metadata.displayNames["en-US"]=="Updated fixture tool","metadata edits invalidate scan cache");}
   var bad=PackageAt(Path.Combine(source,"bad"),"test.bad","Modules/Bad/b.dll");File.WriteAllText(Paths.Safe(bad.Folder,bad.Manifest.files[0].source),"tampered");var plan=BatchPlanner.Build(new[]{good,bad},p=>new Engine(game,state,true));Check(plan.Count(p=>p.Safe)==1&&plan.Count(p=>!p.Safe)==1,"preflight isolates a corrupt source from an independent package");Check(!File.Exists(Paths.Safe(game,target)),"preflight never installs payload files");var overlap=PackageAt(Path.Combine(source,"overlap"),"test.overlap",target);plan=BatchPlanner.Build(new[]{good,overlap},p=>new Engine(game,state,true));Check(plan.All(p=>!p.Safe),"overlapping batch destinations block both packages");var engine=new Engine(game,state,true);var safe=BatchPlanner.Build(new[]{good},p=>engine).Single();engine.Install(safe.Package,safe.Collisions);Check(engine.ReadRegistry().packages.Single().id==identity,"preflight and actual installation retain stable identity");engine.Uninstall(identity);var changed=Packages.Load(good.Folder,"fixture");var originalManifest=File.ReadAllText(Path.Combine(good.Folder,Packages.ManifestName));var altered=Data.Parse<PackageManifest>(originalManifest);altered.version="2.0.0";Data.Write(Path.Combine(good.Folder,Packages.ManifestName),altered);bool versionBlocked=false;try{engine.Install(changed,null);}catch{versionBlocked=true;}Check(versionBlocked&&engine.ReadRegistry().packages.Count==0,"source version changes after confirmation cannot install a different plan");File.WriteAllText(Path.Combine(good.Folder,Packages.ManifestName),originalManifest);Check(!Directory.EnumerateFiles(game,".umm-write-check-*",SearchOption.AllDirectories).Any(),"write permission probes leave no files behind");
   string recoverFile=Paths.Safe(game,"Modules/Recovery/a.dll");Directory.CreateDirectory(Path.GetDirectoryName(recoverFile));File.WriteAllText(recoverFile,"manual edit after crash");string saved="transactions/guard/0.bak";string backup=Paths.Safe(engine.State,saved);Directory.CreateDirectory(Path.GetDirectoryName(backup));File.WriteAllText(backup,"before");var journal=new Journal{schemaVersion=2,gameRoot=game,hadRegistry=false,files=new List<Snapshot>{new Snapshot{target="Modules/Recovery/a.dll",saved=saved,existed=true,hash=Data.Hash(backup),expectedHash=Data.Key("after"),expectedAbsent=false}}};Data.Write(Path.Combine(engine.State,"pending.json"),journal);bool recoveryBlocked=false;try{engine.RecoverPending();}catch{recoveryBlocked=true;}Check(recoveryBlocked&&File.ReadAllText(recoverFile)=="manual edit after crash"&&engine.NeedsRecovery,"new journal refuses to overwrite post-crash manual changes");File.WriteAllText(recoverFile,"before");engine.RecoverPending();Check(!engine.NeedsRecovery&&File.ReadAllText(recoverFile)=="before","matching snapshot remains safely recoverable");
   string realMetadata=Path.Combine(Path.GetFullPath(output),"california-metadata-fixture");if(Directory.Exists(realMetadata)){var scopes=Packages.LoadAll(realMetadata,"fixture");Check(scopes.Count==2&&scopes.All(p=>p.Metadata!=null),"actual California package matches both display metadata identities");foreach(var p in scopes)foreach(string code in L.Languages){L.Language=code;Check(ModNames.Display(p)==p.Metadata.displayNames[code],"actual scope name follows "+code+": "+p.Manifest.scopeId);}}
   Data.Write(Path.Combine(state,"settings.json"),new Settings{gameRoot=game,workshopRoot=source,language="zh-TW",theme="midnight",packageFolders=new List<string>(),versionChoices=new Dictionary<string,string>()});using(var form=new MainForm(root,state,true)){Exception failed=null;form.Shown+=async delegate{try{await form.VerifyDashboard(root,results);}catch(Exception ex){failed=ex;}finally{form.EndFixture();form.Close();}};Application.Run(form);if(failed!=null)System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(failed).Throw();}
   using(var restart=new MainForm(root,state,true)){Check(Themes.Current.Id=="cream","theme preference survives restart");}
   File.WriteAllLines(Path.Combine(root,"dashboard-results.txt"),results);Console.WriteLine("Dashboard artifacts: "+root);return 0;
  }
 }
 public partial class MainForm {
  public async System.Threading.Tasks.Task VerifyDashboard(string output,List<string> results){int scans=scanRuns;var localized=rows.Single(r=>RowId(r)=="test.localized");search.Text="測試工具";CheckVisible(true);var ids=Selected().Select(RowId).ToArray();foreach(int theme in Enumerable.Range(0,4)){ChangeTheme(theme);AssertExperience(Selected().Select(RowId).SequenceEqual(ids)&&scanRuns==scans,"theme switch preserves checks and scan count "+theme,results);AssertExperience(detail.BackColor==Themes.Current.Raised&&grid.DefaultCellStyle.ForeColor==Themes.Current.Text&&themeChoice.SelectedIndex==theme,"theme applies to input, detail and list "+theme,results);foreach(string code in L.Languages){ChangeLanguage(Array.IndexOf(L.Languages,code));AssertExperience(Selected().Select(RowId).SequenceEqual(ids)&&scanRuns==scans&&RawName(localized)==localized.Package.Metadata.displayNames[code],"theme-language combination preserves catalog "+theme+"/"+code,results);using(var dialog=CreateResultDialog(L.Get("Text133"),L.Get("RetryHelp"),new List<string>(),"fixture technical details")){var body=FindControls(dialog).OfType<TextBox>().First();AssertExperience(body.BackColor==Themes.Current.Raised&&body.ForeColor==Themes.Current.Text,"result dialog uses theme and language "+theme+"/"+code,results);}}ChangeLanguage(0);ClientSize=new Size(1366,768);LayoutDetail();PerformLayout();Application.DoEvents();using(var picture=new Bitmap(ClientSize.Width,ClientSize.Height)){Controls[0].DrawToBitmap(picture,new Rectangle(Point.Empty,ClientSize));picture.Save(Path.Combine(output,"theme-"+Themes.Current.Id+".png"));}}
   foreach(string language in L.Languages){ChangeLanguage(Array.IndexOf(L.Languages,language));AssertExperience(RawName(localized)==localized.Package.Metadata.displayNames[language],"live mod name follows UI language "+language,results);AssertExperience(Selected().Count==1&&scanRuns==scans,"name language switch retains checks without scanning "+language,results);AssertExperience(grid.Rows.Cast<DataGridViewRow>().Single(r=>r.Visible).Cells[1].Value.ToString().StartsWith(RawName(localized)),"library renders translated name "+language,results);}
   search.Text="測試工具";AssertExperience(grid.Rows.Cast<DataGridViewRow>().Count(r=>r.Visible)==1,"other-language name remains searchable",results);activityEntries.Add(new ActivityEntry{Time=DateTime.Now,Kind="Info",Module=RowId(localized),Operation="test",Message="fixture"});AssertExperience(ActivityModule(activityEntries.Last())==RawName(localized),"activity resolves a stored module ID at display time",results);
   settings.navigationCollapsed=true;UpdateNavigation();SaveSettings();AssertExperience(dashboardShell.ColumnStyles[0].Width==60&&navButtons.All(b=>hints.GetToolTip(b).Length>0),"collapsed navigation keeps tooltips and persistent state",results);settings.navigationCollapsed=false;UpdateNavigation();
   sourceProblems.Add(new SourceProblem{Folder=rows.Single(r=>RowId(r)=="test.bad").Package.Folder,SummaryKey="UnreadablePackage",RemedyKey="ReloadSourceHelp",Details="fixture unreadable data"});RefreshProblems();AssertExperience(visibleProblems.Any(p=>p.SummaryKey=="UnreadablePackage"),"problem center retains real source diagnostics",results);tabs.SelectedTab=problemPage;PerformLayout();Application.DoEvents();using(var picture=new Bitmap(ClientSize.Width,ClientSize.Height)){Controls[0].DrawToBitmap(picture,new Rectangle(Point.Empty,ClientSize));picture.Save(Path.Combine(output,"problem-center.png"));}
   tabs.SelectedIndex=0;search.Clear();CheckVisible(false);foreach(DataGridViewRow line in grid.Rows)if(RowId(rows[line.Index])=="test.localized"||RowId(rows[line.Index])=="test.bad")line.Cells[0].Value=true;await ExecuteFixtureOperation(()=>Install());AssertExperience(localized.Installed!=null&&rows.Single(r=>RowId(r)=="test.bad").Installed==null&&batchSuccess==1&&batchSkipped==1,"actual batch installs safe item and reports corrupt item as skipped",results);AssertExperience(visibleProblems.Any(p=>p.ModId=="test.bad"),"batch failures link to module identity in problem center",results);search.Text="測試工具";CheckVisible(true);await ExecuteFixtureOperation(()=>Uninstall());AssertExperience(localized.Installed==null,"batch-installed module restores safely",results);
   foreach(Size size in new[]{new Size(1920,1080),new Size(1600,900),new Size(1366,768)}){ClientSize=size;PerformLayout();LayoutDetail();Application.DoEvents();AssertExperience(themeChoice.Right<=themeChoice.Parent.Width&&languageChoice.Right<=languageChoice.Parent.Width&&navButtons.All(b=>b.Right<=navigation.Width),"dashboard controls fit "+size,results);AssertExperience(tabs.Bottom<=dashboardShell.Height&&(!detailSplit.Panel2Collapsed?historyCurrent.Bottom<=historyCurrent.Parent.ClientSize.Height:true),"workspace and detail actions stay inside the viewport "+size,results);tabs.SelectedIndex=1;PerformLayout();Application.DoEvents();AssertExperience(installVersions.Bottom<=installVersions.Parent.ClientSize.Height&&forgetVersions.Bottom<=forgetVersions.Parent.ClientSize.Height,"version command rows reserve room for scrolling "+size,results);tabs.SelectedIndex=0;AssertExperience(detail.SelectionLength==0,"details do not auto-select text "+size,results);}
   ChangeTheme(3);SaveSettings();
  }
 }
